41	     * @param namesakeCount        the owner's namesake count, may be {@code null}
42	     * @param householdMemberCount the number of owners in the owner's household, may be {@code null}
43	     * @param registrationDate     the owner's registration date, may be {@code null}
44	     * @return the membership points, zero or more
45	     */
46	    public static int deriveMembershipPoints(String email, Integer namesakeCount,
47	            Integer householdMemberCount, LocalDate registrationDate) {
48	        int points = 0;
49	        if (email != null && !email.isBlank()) {
50	            points += EMAIL_POINTS;
51	        }
52	        if (namesakeCount != null && namesakeCount == 0) {
53	            points += UNIQUE_NAME_POINTS;
54	        }
55	        if (householdMemberCount != null && householdMemberCount >= GOLD_HOUSEHOLD_SIZE) {
56	            points += HOUSEHOLD_POINTS;
57	        }
58	        if (hasTenure(registrationDate)) {
59	            points += TENURE_POINTS;
60	        }
61	        return points;
62	    }
63	
64	    /**
65	     * Returns the membership level for an owner, mapped from its
66	     * {@link #deriveMembershipPoints membership points}: level 1 (0-1 points),
67	     * level 2 (2-3 points), level 3 (4-5 points) and level 4 (6 or more points).
68	     *
