84	     * @param points the owner's membership points
85	     * @return the membership level, between 1 and 4 inclusive
86	     */
87	    private static int levelForPoints(int points) {
88	        if (points >= 6) {
89	            return 4;
90	        }
91	        if (points >= 4) {
