6	/**
7	 * Derives an owner's 'ageBand' from its birth date as of its registration date.
8	 * Kept out of {@link OwnerMapper} so MapStruct does not mistake it for an
9	 * implicit property mapping method.
10	 */
11	public final class AgeBandResolver {
12	
13	    /** Ages below this are 'MINOR'. */
14	    private static final int ADULT_AGE = 18;
15	
16	    /** Ages at or above this are 'SENIOR'. */
17	    private static final int SENIOR_AGE = 65;
18	
19	    private AgeBandResolver() {
20	    }
21	
22	    /**
23	     * Returns the owner's age band, computed as the whole number of years between
24	     * {@code birthDate} and {@code registrationDate}: 'MINOR' when under 18,
25	     * 'ADULT' when 18 to 64 inclusive and 'SENIOR' when 65 or older.
26	     *
27	     * @param birthDate        the owner's date of birth, may be {@code null}
28	     * @param registrationDate the date the age is evaluated against
29	     * @return the age band, or {@code null} when no birth date was supplied
